\label{LemaExponencial}
Let $S(t)=e^{\mathcal{B}_1t}$  be a $C_0$-semigroup on contractions on Hilbert space                   $\mathcal{H}=\mathcal{H}_1$,  the solutions of the system \eqref{Eq05A}--\eqref{Eq07A} and \eqref{Eq08A}--\eqref{Eq09A}  satisfy the inequality
\begin{equation}\label{EstimaExponential} 
\limsup_{|\lambda|\to\infty}\|(i\lambda I-\mathcal{B}_1) ^{-1}\|_{\mathcal{L}(\mathcal{H})}<\infty.
\end{equation}

To show the \eqref{EstimaExponential} inequality,  it suffices to show that,  given $\delta>0$ there exists a constant $C_\delta>0$ such that  the solutions of the system  \eqref{Eq05A}--\eqref{Eq07A} and \eqref{Eq08A}--\eqref{Eq09A}   for $|\lambda|>\delta$ satisfy the inequality
\begin{equation}\label{EstimaEquivExp1}
 \dfrac{\|U\|_{\mathcal{H}}}{\|F\|_{\mathcal{H}}}\leq C_\delta\Longleftrightarrow \|U\|_{\mathcal{H}}=\|(i\lambda I-\mathcal{B}_1)^{-1} F\|_{\mathcal{H}} \leq C_\delta \|F\|_\mathcal{H}.
\end{equation}
If $\lambda\in \mathbb{R}$ and $F=(f^1,f^2,f^3,f^4, f^5, f^6)\in \mathcal{H}$ then the solution $U=(\phi,\Phi,\psi, \Psi,\theta,\Theta)\in\hbox{D}(\mathcal{B}_1)$ the resolvent equation $(i\lambda I- \mathcal{B}_1)U=F$ can be written in the form


\begin{eqnarray}                        
i\lambda \phi-\Phi &=& f^1\quad\rm{in}\quad D(A^\frac{1}{2}),\label{esp-10}\\
i\lambda \Phi-\frac{\kappa}{\rho_1}(\phi_x+\psi)_x+\frac{\mu_1}{\rho_1}A^\tau \Phi&=& f^2\quad\rm{in}\quad D(A^0),\label{esp-20}\\
i\lambda  \psi-\Psi &=&f^3\quad \rm{in}\quad D(A^\frac{1}{2}),\label{esp-30}\\
i\lambda \Psi+\dfrac{b}{\rho_2}A\psi+\dfrac{\kappa}{\rho_2}(\phi_x+\psi)+\frac{\beta}{\rho_2}\Theta_x+\dfrac{\mu_2}{\rho_2}A^\sigma \Psi &=& f^4 \quad\rm{in}\quad D(A^0),\label{esp-40}\\
i\lambda\theta-\Theta&=&f^5\quad{ \rm in}\quad D(A^\frac{1}{2}),\label{esp-50}\\
i\lambda\Theta+\dfrac{\delta}{\rho_3}A\theta+\dfrac{\gamma}{\rho_3}\Psi_x+\dfrac{K}{\rho_3}A^\xi\Theta&=& f^6\quad {\rm in}\quad D(A^0). \label{esp-60}
\end{eqnarray}
Using the fact that the operator $\mathcal{B}_1$ is dissipative,   result in  
\begin{multline}\label{dis-10}
\beta\gamma\mu_1\|A^\frac{\tau}{2}\Phi\|^2+\kappa\gamma\mu_2\|A^\frac{\sigma}{2} \Psi\|^2+\dfrac{\beta\kappa K^2}{\rho_3}\|A^\frac{\xi}{2}\Theta\|^2
= \text{Re}\langle{(i\lambda -\mathcal{B}_1)U},{U}\rangle\\= \text{Re}\langle{F},{U}\rangle\leq \|F\|_\mathcal{H}\|U\|_\mathcal{H}.
\end{multline}



On the other hand,  performing the duality product of \eqref{esp-20} for $\beta\gamma\rho_1 \phi$,    and remembering that the operators $A^\nu$ for all $\nu\in\mathbb{R}$ are
self-adjoint, resulting in
\begin{multline*}
\beta\kappa\gamma\langle{(\phi_x+\psi)},{\phi_x}\rangle= \beta\gamma\rho_1\|\Phi\|^2+\beta\gamma\rho_1\langle{\Phi},{f^1}\rangle\\
 -i\lambda\mu_1\beta\gamma\|A^\frac{\tau}{2}\phi\|^2
+\mu_1\beta\gamma\langle{A^\frac{\tau}{2} f^1},{A^\frac{\tau}{2} \phi}\rangle
+\beta\gamma\rho_1\langle{f^2},{\phi}\rangle,
\end{multline*}

now performing the duality product of \eqref{esp-40} for $\beta\gamma\rho_2 \psi$,   and remembering that the operators $A^\nu$ for all $\nu\in\mathbb{R}$ are
self-adjoint, leading to

\begin{multline*}
\beta\kappa\gamma\langle{(\phi_x+\psi)},{\psi}\rangle+b\beta\gamma\|A^\frac{1}{2}\psi\|^2=\beta\gamma\rho_2\|\Psi\|^2
+\beta\gamma\rho_2\langle{\Psi},{f^3}\rangle\\
+\beta^2\gamma\langle{\Theta},{\psi_x}\rangle-i\lambda\beta\gamma\mu_2\|A^\frac{\sigma}{2}\psi\|^2+\beta\gamma\mu_2\langle{A^\frac{\sigma}{2}f^3},{A^\frac{\sigma}{2}\psi}\rangle+\beta\gamma\rho_2\langle{f^4},{\psi}\rangle.
\end{multline*}

Adding the last 2 equations, result in 
\begin{multline}\label{Eq001Exponential}
\beta\kappa\gamma\|\phi_x+\psi\|^2+b\beta\gamma\|A^\frac{1}{2}\psi\|^2=
\beta\gamma\rho_1\|\Phi\|^2+\beta\gamma\rho_2\|\Psi\|^2
-i\lambda\beta\gamma\{ \mu_1\|A^\frac{\tau}{2}u\|^2\\
+\mu_2\|A^\frac{\sigma}{2}\psi\|^2\}
 +\beta\gamma\rho_1\langle{\Phi},{f^1}\rangle+\beta\gamma\rho_2\langle{\Psi},{f^3}\rangle\\
+\beta\gamma\mu_1\langle{A^\frac{\tau}{2}f^1},{A^\frac{\tau}{2}\phi}\rangle +\beta\gamma\mu_2\langle{A^\frac{\sigma}{2}f^3},{A^\frac{\sigma}{2}\phi}\rangle\\
+\beta\gamma\rho_1\langle{f^2},{\phi}\rangle+\beta\gamma\rho_2\langle{f^4},{\psi}\rangle+\beta^2\gamma\langle{\Theta},{\psi_x}\rangle.
\end{multline}
Taking real part,  using norm $\|F\|_\mathcal{H}$ and $\|U\|_\mathcal{H}$ and     applying Cauchy-Schwarz and Young,  for $\varepsilon>0$ exists  $C_\varepsilon>0$ which does not depend on $\lambda$,  such that
\begin{multline*}
\beta\kappa\gamma\|\phi_x+\psi\|^2+b\beta\gamma\|A^\frac{1}{2}\psi\|^2 
\leq \beta\gamma\rho_1\|\Phi\|^2+\beta\gamma\rho_2\|\Psi\|^2+\varepsilon\|A^\frac{1}{2}\psi\|^2+C_\varepsilon\|\Theta\|^2
+C_\delta\|F\|_\mathcal{H}\|U\|_\mathcal{H}.
\end{multline*}
From  estimative \eqref{dis-10}  and the fact $0\leq\frac{\tau}{2}, \; 0\leq\frac{\sigma}{2}$  and $0\leq\frac{\xi}{2}$,  the continuous embedding $D(A^{\theta_2}) \hookrightarrow D(A^{\theta_1}),\;\theta_2>\theta_1$,  lead to
\begin{eqnarray}\label{Exponential002}
\beta\kappa\gamma\|\phi_x+\psi\|^2+b\beta\gamma\|A^\frac{1}{2}\psi\|^2&\leq& C_\delta\|F\|_\mathcal{H}\|U\|_\mathcal{H}.
\end{eqnarray}
On the other hand,  performing the duality product of \eqref{esp-60} for $\beta\kappa\rho_3 \theta$,    and remembering that the operators $A^\nu$ for all $\nu\in\mathbb{R}$ are
self-adjoint and from \eqref{esp-50},  result in 
\begin{multline*}
\beta\kappa\delta\|A^\frac{1}{2}\theta\|^2=\delta\beta\kappa\|\Theta\|^2+\beta\kappa\rho_3\langle{\Theta},{f^5}\rangle+\beta\kappa\gamma\langle{\Psi},{\theta_x}\rangle\\
-i\kappa\beta K\lambda\|A^\frac{\xi}{2}\theta\|^2+\kappa\beta K\langle{A^\frac{\xi}{2}f^5},{A^\frac{\xi}{2}\theta}\rangle+\beta\kappa\rho_3\langle{f^6},{\theta}\rangle
\end{multline*}
Taking real part and by using the inequalities Cauchy-Schwarz and Young and norms $\|F\|_\mathcal{H}$ and $\|U\|_\mathcal{H}$,  from $|\lambda|>1$,   for $\varepsilon>0$ exists $C_\varepsilon>0$ which does not depend on $\lambda$ such that
\begin{multline*}
\beta\kappa\delta\|A^\frac{1}{2}\theta\|^2
\leq C\{\|\Theta\|^2+\|\Theta\|\|f^5\|+\|A^\frac{\xi}{2}f^5\|\|A^\frac{\xi}{2}\theta\|+\|f^6\|\|\theta\|\}+C_\varepsilon\|\Psi\|^2+\varepsilon\|A^\frac{1}{2}\theta\|^2.
\end{multline*}
Then, from estimative \eqref{dis-10}  and the fact $0\leq\frac{\sigma}{2}$ and $0\leq\frac{\xi}{2}\leq\frac{1}{2}$  the continuous embedding $D(A^{\theta_2}) \hookrightarrow D(A^{\theta_1}),\;\theta_2>\theta_1$,  lead to
\begin{equation}\label{Exponential003}
\beta\kappa\delta\|A^\frac{1}{2}\theta\|^2\leq C_\delta\|F\|_\mathcal{H}\|U\|_\mathcal{H}.
\end{equation}

Finally,  from estimates \eqref{dis-10}, \eqref{Exponential002} and \eqref{Exponential003},   the proof of this lemma is completed.

\label{Regularidad}
Let $\delta> 0$. There exists a constant $C_\delta > 0$ such that the solutions of the system \eqref{Eq05A}--\eqref{Eq07A} and \eqref{Eq08A}--\eqref{Eq09A}  for $|\lambda|\geq \delta$ satisfy the inequalities
\begin{eqnarray}\label{EqPrincipalLema}
\hspace*{-0.5cm}(i)\; |\lambda|\beta\gamma[\kappa\|\phi_x+\psi\|^2+b\|A^\frac{1}{2}\psi\|^2]\hspace*{-0.25cm} &\leq
&\hspace*{-0.25cm} |\lambda|\beta\gamma[\rho_1\|\Phi\|^2+\rho_2\|\Psi\|^2] +C_\delta\|F\|_\mathcal{H}\|U\|_\mathcal{H}.\\
\nonumber
\\
\label{EqPrincipalLemaA}
(ii)\; \beta\kappa\delta|\lambda|\|A^\frac{1}{2}\theta\|^2 &\leq & \beta\kappa\rho_3|\lambda|\|\Theta\|^2+ C_\delta\|F\|_\mathcal{H}\|U\|_\mathcal{H}.
\end{eqnarray}

{\bf Item $(i)$:} Performing the duality product of \eqref{esp-20} for $\beta\gamma\rho_1\lambda \phi$,   and remembering that the operators $A^\nu$ for all $\nu\in \mathbb{R} $ are self-adjunct,  result in 
\begin{eqnarray*}
\beta\kappa\gamma\lambda\langle{(\phi_x+\psi)},{\phi_x}\rangle& =&\beta\gamma\rho_1\lambda\|\Phi\|^2+\beta \gamma\rho_1\langle{\lambda \Phi},{f^1}\rangle-i\mu_1\beta\gamma\|A^\frac{\tau}{2}\Phi\|^2\\
& & -i\mu_1\beta\gamma\langle{A^\tau \Phi},{f^1}\rangle
+i\beta\gamma\rho_1\langle{f^2},{\Phi}\rangle+i\beta\gamma\rho_1\langle{f^2},{f^1}\rangle.
\end{eqnarray*}

Now performing the duality product of \eqref{esp-40} for $\beta\gamma\rho_2\lambda \psi$,  and remembering that the operators $A^\nu$ for all $\nu\in \mathbb{R} $ are
self-adjunct leads to 

\begin{eqnarray*}
\lambda\beta\gamma[\kappa\langle{(\phi_x+\psi)},{\psi}\rangle+
b\|A^\frac{1}{2}\psi\|^2]
\hspace*{-0.3cm}& = &\hspace*{-0.3cm} \beta\gamma\rho_2\lambda\|\Psi\|^2+\beta\gamma\rho_2\langle{\lambda \Psi},{f^3}\rangle+i\beta^2\gamma\langle{\Theta},{\psi_x}\rangle \\
& &\hspace*{-0.3cm} +i\beta^2\gamma\langle{\Theta},{f_x^3}\rangle  - i\mu_2\beta\gamma\|A^\frac{\sigma}{2}\Psi\|^2-i\mu_2\beta\gamma\langle{A^\sigma \Psi},{f^3}\rangle\\
& & \hspace*{-0.3cm} +i\beta\gamma\rho_2\langle{f^4},{\Psi}\rangle +i\beta\gamma\rho_2\langle{f^4},{f^3}\rangle.
\end{eqnarray*}

Adding the last 2 equations,  result in 
\begin{multline}\label{Eq001Gevrey}
\lambda\beta\gamma[\kappa\|\phi_x+\psi\|^2+b\|A^\frac{1}{2}\psi\|^2] =
\lambda\beta\gamma[\rho_1\|\Phi\|^2+\rho_2\|\Psi\|^2]
-i\beta\gamma\{\mu_1\|A^\frac{\tau}{2}\Phi\|^2\\+\mu_2\|A^\frac{\sigma}{2}\Psi\|^2\}+\beta\gamma\rho_1\langle{\lambda \Phi},{f^1}\rangle+\beta\gamma\rho_2\langle{\lambda \Psi},{f^3}\rangle-i\beta\gamma\{\mu_1 \langle{A^\tau \Phi},{f^1}\rangle\\
+\mu_2\langle{A^\sigma \Psi},{f^3}\rangle \}
+i\beta\gamma\rho_1\langle{f^2},{\Phi}\rangle +i\beta\gamma\rho_2\langle{f^4},{\Psi}\rangle
+i\beta\gamma\rho_1\langle{f^2},{f^1}\rangle\\
+i\beta\gamma\rho_2\langle{f^4},{f^3}\rangle+i\beta^2\gamma\langle{\Theta},{\psi_x}\rangle+i\beta^2\gamma\langle{\Theta},{f_x^3}\rangle.   
\end{multline}
On the other hand, from \eqref{esp-20}  and \eqref{esp-40},  result in 
\begin{multline}\label{Eq002Gevrey}
\beta\gamma\{\rho_1\langle{\lambda \Phi},{f^1}\rangle+\rho_2\langle{\lambda \Psi},{f^3}\rangle\}
 =i\beta\gamma\{\kappa\langle{(\phi_x+\psi)},{f^1_x}\rangle\\
 +\mu_1\langle{A^\tau \Phi},{f^1}\rangle-\rho_1\langle{f^2},{f^1}\rangle
 +b\langle{A^\frac{1}{2}\psi},{A^\frac{1}{2}f^3}\rangle+\kappa\langle{(\phi_x+\psi)},{f^3}\rangle\\
 -\beta\langle{\Theta},{f_x^3}\rangle+\mu_2\langle{A^\sigma \Psi},{f^3}\rangle-\rho_2\langle{f^4},{f^3}\rangle\}.
\end{multline}
Using the identity \eqref{Eq002Gevrey} in the \eqref{Eq001Gevrey} equation and simplifying,  lead to 
\begin{multline}\label{Eq003Gevrey}
\lambda\beta\gamma[\kappa\|\phi_x+\psi\|^2+b\|A^\frac{1}{2}\psi\|^2] =
\lambda\beta\gamma[\rho_1\|\Phi\|^2+\rho_2\|\Psi\|^2]
\\-i\{\mu_1\|A^\frac{\tau}{2}\Phi\|^2
+\mu_2\|A^\frac{\sigma}{2}\Psi\|^2\}
+i\beta\gamma\kappa\langle{\phi_x},{f_x^1}\rangle+i\beta\gamma\kappa\langle{\psi},{f_x^1}\rangle\\+ib\beta\gamma\langle{A^\frac{1}{2}\psi},{A^\frac{1}{2}f^3}\rangle
i\beta\gamma\kappa\langle{\phi_x},{f^3}\rangle+i\beta\gamma\kappa\langle{\psi},{f^3}\rangle\\
+i\beta\gamma\rho_1\langle{f^2},{\Phi}\rangle
+i\beta\gamma\rho_2\langle{f^4},{\Psi}\rangle+i\beta^2\gamma\langle{\Theta},{\psi_x}\rangle.
\end{multline}
As for $\varepsilon>0$  exists $C_\varepsilon>$ such that  $|i\beta^2\gamma\langle{\Theta},{\psi_x}\rangle|\leq \varepsilon\|A^\frac{1}{2}\psi\|^2+C_\varepsilon\|\Theta\|^2$, taking the real part,  and applying the Cauchy-Schwarz and Young inequalities,   estimative \eqref{EstimaEquivExp1}  of Lemma\eqref{LemaExponencial} and using the definitions of the $F$ and $U$ norm in \eqref{Eq003Gevrey}  the proof of item $(i)$  this lemma is completed.

On the other hand,  performing the duality product of \eqref{esp-60} for $\beta\kappa\rho_3\lambda \theta$,   and remembering that the operators $A^\theta$ for all $\theta\in \mathbb{R} $ are self-adjunct,  result in
\begin{multline}
\beta\kappa\delta\lambda\|A^\frac{1}{2}\theta\|^2=\beta\kappa\rho_3\langle{\lambda \Theta},{i\lambda\theta}\rangle-\beta\kappa\gamma\langle{\psi_x},{\lambda\theta}\rangle
+\beta\kappa K\langle{A^\xi\Theta},{\lambda\theta}\rangle+\beta\kappa\rho_3\langle{f^6},{\lambda\theta}\rangle.
\label{Eq000Ltheta}
\end{multline}
As
\begin{eqnarray}
\label{Eq001Ltheta}
\rho_3\langle{\lambda \Theta},{i\lambda\theta}\rangle&=&
\rho_3\lambda\|\Theta\|^2+i\delta\langle{A^\frac{1}{2}\theta},{A^\frac{1}{2}f^5}\rangle-i\gamma\langle{\Psi},{f^5_x}\rangle +i K\langle{A^\xi\Theta},{f^5}\rangle -i\rho_3\langle{f^6},{f^5}\rangle.\\
\label{Eq002Ltheta}
-\gamma\langle{\psi_x},{\lambda\theta}\rangle &=&-i\gamma\langle{\psi_x},{\Theta}\rangle-i\gamma\langle{\psi_x},{f^5}\rangle.\\
\label{Eq003Ltheta}
 K\langle{A^\xi\Theta},{\lambda\theta}\rangle &=& -i K\|A^\frac{\xi}{2}\Theta\|^2-i K\langle{A^\xi\Theta},{f^5}\rangle.
\\
\label{Eq004Ltheta}
\rho_3\langle{f^6},{\lambda\theta}\rangle &= & i\rho_3\langle{f^6},{\Theta}\rangle+i\rho_3\langle{f^6},{f^5}\rangle.
\end{eqnarray}
Using \eqref{Eq001Ltheta}--\eqref{Eq004Ltheta} in \eqref{Eq000Ltheta},  lead to
\begin{multline}\label{Eq005Ltheta}
\beta\kappa\delta\lambda\|A^\frac{1}{2}\theta\|^2 = \beta\kappa\rho_3\lambda\|\Theta\|^2+i\beta\kappa\delta\langle{A^\frac{1}{2}\theta},{A^\frac{1}{2}f^5}\rangle-i\beta\kappa\gamma\langle{\Psi},{f^5_x}\rangle-i\beta\kappa\gamma\langle{\psi_x},{\Theta}\rangle\\
 -i\beta\kappa\gamma\langle{\psi_x},{f^5}\rangle-i\beta\kappa K\|A^\frac{\xi}{2}\Theta\|^2
 +i\beta\kappa\rho_3\langle{f^6},{\Theta}\rangle.
\end{multline}

Taking real part of the equation \eqref{Eq005Ltheta} and using the inequalities Cauchy-Schwarz and Young and norms $\|F\|_\mathcal{H}$ and $\|U\|_\mathcal{H}$,  from $|\lambda|>1$,   for $\varepsilon>0$ exists $C_\varepsilon>0$ such that 
\begin{multline*}
\beta\kappa\delta|\lambda|\|A^\frac{1}{2}\theta\|^2 \leq\beta\kappa\rho_3|\lambda|\|\Theta\|^2+ C\{\|A^\frac{1}{2}\theta\|\|A^\frac{1}{2}f^5\|+\|\Psi\|\|f^5_x\|\\
+\|\psi_x\|^2+\|\Theta\|^2+\|\psi_x\|\|f^5\|+\|f^6\|\|\theta\| \}.
\end{multline*}
Then, from Lemma\eqref{LemaExponencial} and  as $\|\psi_x\|^2=\|A^\frac{1}{2}\psi\|^2$,   the proof of item $(ii)$ of this lemma is finished.

\label{Def1.1Tebou} Let $t_0\geq 0$ be a real number.  A strongly continuous semigroup $S(t)$, defined on a Banach space $ \mathcal{H}$, is of Gevrey class $s > 1$ for $t > t_0$, if $S(t)$ is infinitely differentiable for $t > t_0$, and for every compact set $K \subset (t_0,\infty)$ and each $\mu > 0$, there exists a constant $ C = C(\mu, K) > 0$ such that
	\begin{equation}\label{DesigDef1.1}
	||S^{(n)}(t)||_{\mathcal{L}( \mathcal{H})} \leq  C\mu ^n(n!)^s,  \text{ for all } \quad t \in K, n = 0,1,2...
	\end{equation}

\label{Theorem1.2Tebon}
	Let $S(t)$  be a strongly continuous and bounded semigroup on a Hilbert space $ \mathcal{H}$. Suppose that the infinitesimal generator $\mathcal{B}$ of the semigroup $S(t)$ satisfies the following estimate, for some $0 < \eta < 1$:
	\begin{equation}\label{Eq1.5Tebon2020}
	\lim\limits_{|\lambda|\to\infty} \sup |\lambda |^\eta ||(i\lambda I-\mathcal{B})^{-1}||_{\mathcal{L}( \mathcal{H})} < \infty. 
	\end{equation}
	Then $S(t)$  is of Gevrey  class  $s$   for $t>0$, for every   $s>\dfrac{1}{\eta}$.

From the resolvent  equation $F=(i\lambda I-\mathcal{B}_1)U$  for $\lambda\in\mathbb{R}$,  
$U=(i\lambda I-\mathcal{B}_1)^{-1}F$.  Furthermore,  show  \eqref{Eq1.5Tebon2020} of  theorem\eqref{Theorem1.2Tebon} it is enough to show,  that for $\varepsilon>0$ exists $C_\delta>0$,  such that:

$$\dfrac{|\lambda|^\frac{2r}{r+1} \|(i\lambda-\mathcal{B}_1)^{-1}F\|_\mathcal{H}}{\|F\|_\mathcal{H}}\leq C_\delta \Longleftrightarrow |\lambda |^\frac{2r}{r+1} \|U\|_\mathcal{H}\leq C_\delta \|F\|_\mathcal{H}, \qquad F\in\mathcal{H}\quad{\rm and}\quad  C_\delta>0.$$
Equivalent to
\begin{equation}\label{EstimaEquivalenteGevrey}
|\lambda |^\frac{2r}{r+1}\|U\|_\mathcal{H}^2\leq C_\delta\{\|F\|_\mathcal{H}\|U\|_\mathcal{H}\}\quad\rm{for}\quad \frac{2r}{r+1} \in(0,1).
\end{equation}
where  $r=\min\{\tau,\sigma,\xi\}$, \; for all $(\tau,\sigma,\xi)\in (0,1)^3$.


Next,  $[|\lambda|^\frac{2\tau}{1+\tau}\|\Phi\|+|\lambda|^\frac{2\sigma}{1+\sigma}\|\Psi\|+|\lambda|^\frac{2\xi}{1+\xi}\|\Theta\|]$  will be estimated.  \\





{\bf  Let's start by estimating the term $|\lambda|^\frac{2\tau}{1+\tau}\|\Phi\|$:}  It is  assume that   $|\lambda|>1$,  some ideas could be borrowed  from \cite{LiuR95}.  Set $\Phi=\Phi_1+\Phi_2$, where $\Phi_1\in D(A)$ and $\Phi_2\in D(A^0)$, with 
\begin{equation}\label{Eq110AnalyRR}
i\lambda \Phi_1+A \Phi_1=f^2, 
\hspace{3cm} i\lambda \Phi_2=\dfrac{\kappa}{\rho_1}A\phi+\dfrac{\kappa}{\rho_1}\psi_x-\dfrac{\mu_1}{\rho_1}A^\tau \Phi+A\Phi_1.
\end{equation} 
Firstly,  applying in the product duality  the first equation in \eqref{Eq110AnalyRR} by $\Phi_1$, then  by $A\Phi_1$    and recalling that the operator $A$  is
self-adjoint, resulting in 
\begin{equation}\label{Eq112AnalyRR}
|\lambda|\|\Phi_1\|+|\lambda|^\frac{1}{2}\|A^\frac{1}{2}\Phi_1\|+\|A\Phi_1\|\leq C\|F\|_\mathcal{H}.
\end{equation}
Applying the $A^{-\frac{1}{2}}$ operator on the second equation of \eqref{Eq110AnalyRR},   result in
\begin{equation*}
i\lambda A^{-\frac{1}{2}}\Phi_2= \dfrac{\kappa}{\rho_1}A^\frac{1}{2}\phi+\dfrac{\kappa}{\rho_1}A^{-\frac{1}{2}}\psi_x-\dfrac{\mu_1}{\rho_1}A^{\tau-\frac{1}{2}} \Phi+A^\frac{1}{2}\Phi_1,
\end{equation*}
 then,  as $\|A^{-\frac{1}{2}}\psi_x\|^2=\langle{-A^{-\frac{1}{2}}\psi_{xx}},{A^{-\frac{1}{2}}\psi}\rangle=\langle{A^\frac{1}{2}\psi},{A^{-\frac{1}{2}}\psi}\rangle=\|\psi\|^2$  and  $\tau-\frac{1}{2}\leq \frac{\tau}{2}$ taking into account the continuous embedding $D(A^{\theta_2}) \hookrightarrow D(A^{\theta_1}),\;\theta_2>\theta_1$,  result in 
\begin{equation}\label{Eq113AAnaly}
|\lambda|\|A^{-\frac{1}{2}} \Phi_2\|\leq C\{\|A^\frac{1}{2}\phi\|+ \|\psi\|+\|A^\frac{\tau}{2}\Phi\|\}+\|A^\frac{1}{2}\Phi_1\|,
\end{equation}
using  \eqref{EstimaEquivExp1}, \eqref{dis-10} and  estimative  \eqref{Eq112AnalyRR} ($\|A^\frac{1}{2}\Phi\|^2\leq C|\lambda|^{-1}\|F\|^2_\mathcal{H}$),  lead  to
\begin{equation*}                     
|\lambda|^2\|A^{-\frac{1}{2}}\Phi_2\|^2\leq C\{\|F\|_\mathcal{H}\|U\|_\mathcal{H} +|\lambda|^{-1}\|F\|^2_\mathcal{H} \}.
\end{equation*}
Equivalently 
\begin{equation}
\label{Eq113AnalyRR}
\|A^{-\frac{1}{2}}\Phi_2\|^2\leq C|\lambda|^{-\frac{4\tau+2}{\tau+1}}\{ |\lambda|^\frac{2\tau}{\tau+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\}\quad {\rm for}\quad 0\leq\tau\leq 1.
\end{equation}
On the  other hand, from $\Phi_2=\Phi-\Phi_1$,  \eqref{dis-10} and  as $\frac{\tau}{2}\leq\frac{1}{2}$ the inequality of \eqref{Eq112AnalyRR}, result in
\begin{eqnarray}
\nonumber
\|A^\frac{\tau}{2} \Phi_2\|^2 & \leq & C\{ \|A^\frac{\tau}{2} \Phi\|^2+\|A^\frac{\tau}{2}\Phi_1\|^2
\}\\
\label{Eq114AnalyRR}
 &\leq &  C\{\|F\|_\mathcal{H}\|U\|_\mathcal{H}+|\lambda|^{-1}\|F\|^2_\mathcal{H} \}\leq C|\lambda|^{-\frac{2\tau}{\tau+1}}\{ |\lambda|^\frac{2\tau}{\tau+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\}.
\end{eqnarray}
By Lions' interpolations inequality $0\in [-\frac{1}{2},\frac{\tau}{2}]$,  result in
\begin{equation}\label{Eq115AnalyRR}
 \|\Phi_2\|^2\leq C(\|A^{-\frac{1}{2}}\Phi_2\|^2)^\frac{\tau}{1+\tau}(\|A^\frac{\tau}{2}\Phi_2\|^2)^\frac{1}{1+\tau}.
\end{equation}
Then, using \eqref{Eq113AnalyRR} and \eqref{Eq114AnalyRR} in \eqref{Eq115AnalyRR}, for $ |\lambda|>1$,  result in 
\begin{equation}\label{Eq118AnalyRR}
 \|\Phi_2\|^2\leq C|\lambda|^{-\frac{4\tau}{1+\tau}}\{|\lambda|^\frac{2\tau}{\tau+1} \|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\}.
\end{equation}
Therefore,   as $\|\Phi\|^2\leq  \|\Phi_1\|^2+ \|\Phi_2\|^2$ from first inequality of  \eqref{Eq112AnalyRR},  \eqref{Eq118AnalyRR}, we get
\begin{equation*}
\|\Phi\|^2\leq C|\lambda|^{-2}\|F\|^2_\mathcal{H}+ C|\lambda|^{-\frac{4\tau}{1+\tau}}\{|\lambda|^\frac{2\tau}{\tau+1} \|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\},
\end{equation*}
 and  as for  $0\leq\tau\leq 1$ we have $|\lambda|^{-2}\leq |\lambda|^\frac{-4\tau}{1+\tau}$, result in 
\begin{equation}\label{Eq119AnalyRR}
 |\lambda|\|\Phi\|^2\leq C_\delta|\lambda|^\frac{1-3\tau}{1+\tau}\{|\lambda|^\frac{2\tau}{1+\tau}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\}\qquad\rm{for} \qquad 0\leq\tau\leq 1.
\end{equation}


{\bf On the other hand,   let's now estimate the missing term  $|\lambda|^\frac{2\sigma}{1+\sigma}\|\Psi\|$: } It is assumed that $|\lambda|>1$.  Set $\Psi=\Psi_1+\Psi_2$, where $\Psi_1\in D(A)$ and $\Psi_2\in D(A^0)$, with 
\begin{multline}\label{Eq110AnalyRRW}
i\lambda \Psi_1+A \Psi_1=f^4 \qquad {\rm and}\qquad i\lambda \Psi_2=-\dfrac{b}{\rho_2}A\psi -\dfrac{\kappa}{\rho_2}\phi_x-\dfrac{\kappa}{\rho_2}\psi-\dfrac{\beta}{\rho_2}\Theta_x-\dfrac{\mu_2}{\rho_2}A^\sigma \Psi+A\Psi_1.
\end{multline} 
Firstly,  applying in the product duality  the first equation in \eqref{Eq110AnalyRRW} by $\Psi_1$, then  by $A\Psi_1$    and recalling that the operator $A$  is
self-adjoint, resulting in 
\begin{equation}\label{Eq112AnalyRRW}
|\lambda|\|\Psi_1\|+|\lambda|^\frac{1}{2}\|A^\frac{1}{2}\Psi_1\|+\|A\Psi_1\|\leq C\|F\|_\mathcal{H}. 
\end{equation}

As follows from the second equation in \eqref{Eq110AnalyRRW}  that
\begin{equation*}
i\lambda A^{-\frac{1}{2}}\Psi_2= -\dfrac{b}{\rho_2}A^\frac{1}{2}\psi-\dfrac{\kappa}{\rho_2}A^{-\frac{1}{2}}\phi_x-\dfrac{\kappa}{\rho_2}A^{-\frac{1}{2}}\psi-\dfrac{\beta}{\rho_2}A^{-\frac{1}{2}}\Theta_x-\dfrac{\mu_2}{\rho_2}A^{\sigma-\frac{1}{2}}\Psi+A^\frac{1}{2}\Psi_1,
\end{equation*}
 then,  as $\|A^{-\frac{1}{2}}\phi_x\|^2=\langle{-A^{-\frac{1}{2}}\phi_{xx}},{A^{-\frac{1}{2}}\phi}\rangle=\|\phi\|^2$,  $\|A^{-\frac{1}{2}}\Theta_x\|^2=\|\Theta\|^2 $ and  $\sigma-\frac{1}{2}\leq \frac{\sigma}{2}$ taking into account the continuous embedding $D(A^{\theta_2}) \hookrightarrow D(A^{\theta_1}),\;\theta_2>\theta_1$,  lead to
\begin{equation}\label{Eq113AAnalyRRW}
|\lambda|\|A^{-\frac{1}{2}} \Psi_2\|\leq C\{ \|A^\frac{1}{2}\phi\|+\|\psi\|+\|\Theta\|+\|A^\frac{\sigma}{2}\Psi\|\}+\|A^\frac{1}{2}\Psi_1\|
\end{equation}
Using estimative \eqref{EstimaEquivExp1} and   estimative  \eqref{Eq112AnalyRRW},  for $|\lambda|>1$,  result in
\begin{equation*}
\|A^{-\frac{1}{2}}\Psi_2\|^2 \leq  C|\lambda|^{-3}\{|\lambda|\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\}.
\end{equation*}
Equivalently
\begin{equation}\label{Eq113AnalyRRW}
\|A^{-\frac{1}{2}}\Psi_2\|^2 \leq C|\lambda|^{-\frac{4\sigma+2}{\sigma+1}}\{ |\lambda|^\frac{2\sigma}{\sigma+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\}\quad {\rm for}\quad 0\leq \sigma\leq 1.
\end{equation}
On the  other hand, from $\Psi_2=\Psi-\Psi_1$,  \eqref{dis-10} and  as $\frac{\sigma}{2}\leq\frac{1}{2}$ the  inequality  \eqref{Eq112AnalyRRW},  result in  
\begin{eqnarray}
\nonumber
\|A^\frac{\sigma}{2} \Psi_2\|^ 2& \leq & C\{ \|A^\frac{\sigma}{2} \Psi\|^2+\|A^\frac{\sigma}{2}\Psi_1\|^2\}\\
\label{Eq114AnalyRRW}
& \leq &   C\{\|F\|_\mathcal{H}\|U\|_\mathcal{H}+|\lambda|^{-1}\|F\|^2_\mathcal{H}\}
\leq |\lambda|^{-\frac{2\sigma}{\sigma+1}}\{|\lambda|^\frac{2\sigma}{\sigma+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\}.
\end{eqnarray}
Now,  by Lions' interpolations inequality $0\in [-\frac{1}{2},\frac{\sigma}{2}]$,  lead to
\begin{equation}\label{Eq115AnalyRRW}
 \|\Psi_2\|^2 \leq C (\|A^{-\frac{1}{2}}\Psi_2\|^2)^\frac{\sigma}{1+\sigma}(\|A^\frac{\sigma}{2}\Psi_2\|^2)^\frac{1}{1+\sigma}.
\end{equation}
Then, using \eqref{Eq113AnalyRRW} and \eqref{Eq114AnalyRRW} in \eqref{Eq115AnalyRRW}, for $ |\lambda|>1$,  result in 
\begin{equation}\label{Eq118AnalyRRW}
 \|\Psi_2\|^2 \leq C|\lambda|^{\frac{-4\sigma}{(1+\sigma)}}\{|\lambda|^\frac{2\sigma}{\sigma+1} \|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|_\mathcal{H}\}.
\end{equation}
Therefore,   as $\|\Psi\|^2\leq  \|\Psi_1\|^2+ \|\Psi_2\|^2$ from first inequality of  \eqref{Eq112AnalyRRW}, \eqref{Eq118AnalyRRW} and $|\lambda|^{-2}\leq|\lambda|^\frac{-4\sigma}{1+\sigma}$,  result in 
\begin{equation}\label{Eq119AnalyRRW}
|\lambda|\|\Psi\|^2\leq |\lambda|^\frac{1-3\sigma}{1+\sigma}\{|\lambda|^\frac{2\sigma}{\sigma+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\}\qquad\rm{for}\qquad 0\leq\sigma\leq 1.
\end{equation}


{\bf  Finally,   let's now estimate the missing term  $|\lambda|^\frac{2\xi}{1+\xi}\|\Theta\|$:}   Now we assume  $|\lambda|>1$.  Set $\Theta=\Theta_1+\Theta_2$, where $\Theta_1\in D(A)$ and $\Theta_2\in D(A^0)$, with 
\begin{equation}\label{Eq110AnalyRRT}
i\lambda \Theta_1+A \Theta_1=f^6 
\qquad{\rm and}\qquad 
 i\lambda \Theta_2=-\dfrac{\delta}{\rho_3}A\theta -\dfrac{\gamma}{\rho_3}\Psi_x-\dfrac{K}{\rho_3}A^\xi \Theta+A\Theta_1.
\end{equation} 

Firstly,  applying in the product duality  the first equation in \eqref{Eq110AnalyRRT} by $\Theta_1$, then  by $A\Theta_1$    and recalling that the operator $A$  is
self-adjoint, resulting in 
\begin{equation}\label{Eq112AnalyRRT}
|\lambda|\|\Theta_1\|+|\lambda|^\frac{1}{2}\|A^\frac{1}{2}\Theta_1\|+\|A\Theta_1\|\leq C\|F\|_\mathcal{H}. 
\end{equation}


As follows from the second equation in \eqref{Eq110AnalyRRT}  that
\begin{equation*}
i\lambda A^{-\frac{1}{2}}\Theta_2= -\dfrac{\delta}{\rho_3}A^\frac{1}{2}\theta -\dfrac{\gamma}{\rho_3}A^{-\frac{1}{2}}\Psi_x-\dfrac{K}{\rho_3}A^{\xi-\frac{1}{2}} \Theta+A^\frac{1}{2}\Theta_1,
\end{equation*}
 then,  as  $\|A^{-\frac{1}{2}}\Psi_x\|^2=\|\Psi\|^2 $ and  $-\frac{1}{2}\leq 0$,  $\xi-\frac{1}{2}\leq \frac{\xi}{2}$ taking into account the continuous embedding $D(A^{\theta_2}) \hookrightarrow D(A^{\theta_1}),\;\theta_2>\theta_1$,  result in 
\begin{equation}\label{Eq113AAnalyRRT}
|\lambda|\|A^{-\frac{1}{2}} \Theta_2\|\leq C\{ \|A^\frac{1}{2}\theta\|+\|A^\frac{\xi}{2}\Theta\|+\|\Psi\|\}+\|A^\frac{1}{2}\Theta_1\|
\end{equation}

Using estimates \eqref{EstimaEquivExp1}, \eqref{dis-10} and   estimative  \eqref{Eq112AnalyRRT},  for $|\lambda|>1$,  lead to
\begin{equation}\label{Eq113AnalyRRT}
\|A^{-\frac{1}{2}}\Theta_2\|^2\leq C|\lambda|^{-\frac{4\xi+2}{\xi+1}}\{|\lambda|^\frac{2\xi}{\xi+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\}.
\end{equation}
On the  other hand, from $\Theta_2=\Theta-\Theta_1$,  \eqref{dis-10} and  as $\frac{\xi}{2}\leq\frac{1}{2}$ the inequality  \eqref{Eq112AnalyRRT},   result in 
\begin{eqnarray}
\nonumber
\|A^\frac{\xi}{2} \Theta_2\|^2 & \leq & C\{ \|A^\frac{\xi}{2} \Theta\|^2+\|A^\frac{\xi}{2}\Theta_1\|^2\}\\
\label{Eq114AnalyRRT}
& \leq &   C|\lambda|^{-\frac{2\xi}{\xi+1}}\{|\lambda|^\frac{2\xi}{\xi+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\}.
\end{eqnarray}
Now,  by Lions' interpolations inequality $0\in [-\frac{1}{2},\frac{\xi}{2}]$,   result in 
\begin{equation}\label{Eq115AnalyRRT}
\|\Theta_2\|^2\leq C (\|A^{-\frac{1}{2}}\Theta_2\|^2)^\frac{\xi}{1+\xi}(\|A^\frac{\xi}{2}\Theta_2\|^2)^\frac{1}{1+\xi}.
\end{equation}
Then, using \eqref{Eq113AnalyRRT} and \eqref{Eq114AnalyRRT} in \eqref{Eq115AnalyRRT}, for $ |\lambda|>1$,  result in 
\begin{equation}\label{Eq118AnalyRRT}
 \|\Theta_2\|^2\leq C|\lambda|^{\frac{-4\xi}{(1+\xi)}}\{|\lambda|^\frac{2\xi}{\xi+1} \|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|_\mathcal{H}\}.
\end{equation}
Therefore,   as $\|\Theta\|^2\leq \|\Theta_1\|^2+ \|\Theta_2\|^2$ from first inequality of  \eqref{Eq112AnalyRRT}, estimative \eqref{Eq118AnalyRRT} and $|\lambda|^{-2}\leq |\lambda|^\frac{-4\xi}{1+\xi}$,   result in 
\begin{equation}\label{Eq119AnalyRRT} 
|\lambda|\|\Theta\|^2\leq C_\delta |\lambda|^\frac{1-3\xi}{1+\xi}\{|\lambda|^\frac{2\xi}{\xi+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\}\qquad \rm{for}\qquad 0\leq\xi\leq 1.
\end{equation}


Using the estimates  \eqref{Eq119AnalyRR}   and \eqref{Eq119AnalyRRW}  in the inequality item $(i)$ of Lemma \ref{Regularidad},   result in 
\begin{multline}\label{Eq020GevreyA}
\beta\gamma\kappa\|\phi_x+\psi\|^2+\beta\gamma b\|A^\frac{1}{2}\psi\|^2
 \leq
C_\delta\big\{ |\lambda|^\frac{-2\tau}{1+\tau}+|\lambda|^\frac{-2\sigma}{1+\sigma}+|\lambda|^{-1}\big\}\|F\|_\mathcal{H}\|U\|_\mathcal{H}\\
+\big\{|\lambda|^{-\frac{4\tau}{\tau+1}}+|\lambda|^{-\frac{4\sigma}{\sigma+1}}\big\}\|F\|^2_\mathcal{H}. 
\end{multline}
As $ \tau\leq \sigma \Longrightarrow -\frac{\tau}{\tau+1}\geq -\frac{\sigma}{\sigma+1}$\quad  and \quad  $ \tau\geq \sigma \Longrightarrow -\frac{\tau}{\tau+1}\leq -\frac{\sigma}{\sigma+1}$, we obtain
\begin{multline}\label{Eq020Gevrey}
|\lambda|\{ \beta\gamma\kappa\|\phi_x+\psi\|^2+\beta\gamma b\|A^\frac{1}{2}\psi\|^2
  \}\\
  \leq C_\delta\left\{ \begin{array}{ccc}
  |\lambda|^\frac{1-3\tau}{\tau+1}\{|\lambda|^\frac{2\tau}{\tau+1} \|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\} & \text{for} & \tau\leq \sigma\\\\
 |\lambda|^\frac{1-3\sigma}{\sigma+1}\{ |\lambda|^\frac{2\sigma}{\sigma+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H} \}   &\text{for}  & \sigma\leq \tau
\end{array}   \right.
\end{multline}
Furthermore, using estimative \eqref{Eq119AnalyRRT} in  estimate \eqref{EqPrincipalLemaA} (item $(ii)$ of the Lemma \ref{Regularidad}) and as $\frac{1-3\xi}{\xi+1}+\frac{2\xi}{\xi+1}=\frac{1-\xi}{\xi+1}>0$, we have
\begin{multline}
\label{Eq021Gevrey}
\beta\kappa\delta |\lambda| \|A^\frac{1}{2}\theta\|^2 \leq \beta\kappa\rho_3|\lambda| \|\Theta\|^2+C_\delta|\|F\|_\mathcal{H}\|U\|_\mathcal{H}
\leq C_\delta|\lambda|^\frac{1-3\xi}{1+\xi}\{|\lambda|^\frac{2\xi}{1+\xi}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\}. 
\end{multline}

Finally summing the estimates \eqref{Eq119AnalyRR},\eqref{Eq119AnalyRRW}, \eqref{Eq119AnalyRRT},\eqref{Eq020Gevrey} and \eqref{Eq021Gevrey},  we have
\begin{equation*}
|\lambda|\|U\|^2_\mathcal{H}\leq C_\delta\left\{  \begin{array}{ccc}
 |\lambda|^\frac{1-3\tau}{1+\tau}\{ |\lambda|^\frac{2\tau}{\tau+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\} &\text{for} & \tau\leq \sigma\quad{\rm and}\quad \tau\leq \xi, 
 \\\\
  |\lambda|^\frac{1-3\sigma}{1+\sigma}\{ |\lambda|^\frac{2\sigma}{\sigma+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\} &\text{for} & \sigma \leq \tau\quad{\rm and}\quad \sigma\leq \xi,\\\\
   |\lambda|^\frac{1-3\xi}{1+\xi}\{ |\lambda|^\frac{2\xi}{\xi+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\} &\text{for} & \xi\leq \sigma\quad{\rm and}\quad \xi\leq \tau.
\end{array}\right.
\end{equation*} for $(\tau,\sigma,\xi)\in [0,1]^3$, equivalently
\begin{equation*}
\|U\|^2_\mathcal{H}\leq C_\delta\left\{  \begin{array}{ccc}
 |\lambda|^\frac{-4\tau}{1+\tau}\{ |\lambda|^\frac{2\tau}{\tau+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\} &\text{for} & \tau\leq \sigma\quad{\rm and}\quad \tau\leq \xi, 
 \\\\
  |\lambda|^\frac{-4\sigma}{1+\sigma}\{ |\lambda|^\frac{2\sigma}{\sigma+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\} &\text{for} & \sigma \leq \tau\quad{\rm and}\quad \sigma\leq \xi,\\\\
   |\lambda|^\frac{-4\xi}{1+\xi}\{ |\lambda|^\frac{2\xi}{\xi+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\} &\text{for} & \xi\leq \sigma\quad{\rm and}\quad \xi\leq \tau.
\end{array}\right.
\end{equation*}
Finally, applying Young inequality, we have 
\begin{equation*}
\left\{  \begin{array}{ccc}
 |\lambda|^\frac{2\tau}{\tau+1}\|U\|_\mathcal{H}\leq C_\delta|\|F\|_\mathcal{H} &\text{for} & \tau\leq \sigma\quad{\rm and}\quad \tau\leq \xi, 
 \\\\
  |\lambda|^\frac{2\sigma}{1+\sigma}\|U\|_\mathcal{H}\leq C_\delta\|F\|_\mathcal{H} &\text{for} & \sigma \leq \tau\quad{\rm and}\quad \sigma\leq \xi,\\\\
   |\lambda|^\frac{2\xi}{1+\xi}\|U\|_\mathcal{H}\leq C_\delta \|F\|_\mathcal{H} & \text{for} & \xi\leq \sigma\quad{\rm and}\quad \xi\leq \tau.
\end{array}\right.
\end{equation*}
Therefore,  proof of this theorem is finished.

\label{LiuZAnalyticity}
	Let $S(t)=e^{\mathcal{B}t}$ be $C_0$-semigroup of contractions  on a Hilbert space $ \mathcal{H}$.  Suppose that
	\begin{equation}\label{EixoImaginary}
	\rho(\mathcal{B})\supseteq\{ i\lambda/ \lambda\in {\mathbb R} \} 	\equiv i{\mathbb R}
	\end{equation}
	 Then $S(t)$ is analytic if and only if
	\begin{equation}\label{Analiticity}
	 \limsup\limits_{|\lambda|\to
		\infty}
	\|\lambda(i\lambda I-\mathcal{B})^{-1}\|_{\mathcal{L}( \mathcal{H})}<\infty
	\end{equation}
	holds.

\label{EixoImaginary01}
The $C_0-$semigroup  of contractions $S(t)=e^{\mathcal{B}_1t}$ satisfies the condition 
 \begin{equation}\label{EixoImaginary01A}
	\rho(\mathcal{B}_1)\supseteq\{ i\lambda/ \lambda\in {\mathbb R} \} 	\equiv i{\mathbb R}.
	\end{equation}

Let's prove $i{\mathbb R}\subset\rho( \mathcal{B}_1)$  by contradiction,  it is  supposed  that $i{\mathbb R}\not\subset \rho( \mathcal{B}_1)$. As $0\in\rho( \mathcal{B}_1)$ and  $\rho( \mathcal{B}_1)$ is open,  the highest positive number $\lambda_0$  is considered  such that the interval  $(-i\lambda_0,i\lambda_0)\subset\rho( \mathcal{B}_1)$,  then $i\lambda_0$ or $-i\lambda_0$ is an element of the spectrum $\sigma( \mathcal{B}_1)$.  It is supposed that $i\lambda_0\in \sigma( \mathcal{B}_1)$ (if $-i\lambda_0\in \sigma( \mathcal{B}_1)$ the proceeding is similar). Then, for $0<\nu<\lambda_0$ there exist a sequence of real numbers $(\lambda_n)$, with $0<\nu\leq\lambda_n<\lambda_0$, $\lambda_n\to \lambda_0$, and a vector sequence  $U_n=(\phi_n,\Phi_n,\psi_n,\Psi_n, \theta_n,\Theta_n)\in \mathcal{D}( \mathcal{B}_1)$ with  unitary norms, such that
\begin{eqnarray*}
\|(i\lambda_n- \mathcal{B}_1) U_n\|_\mathcal{H}=\|F_n\|_\mathcal{H}\to 0,
\end{eqnarray*}
as $n\to \infty$. From \eqref{Exponential002} for $0\leq\tau\leq 1$ and $0\leq\sigma\leq 1$,  result in  
\begin{eqnarray*}
\beta\kappa\gamma\|\phi_{xn}+\psi_n\|^2+b\beta\gamma\|A^\frac{1}{2}\psi_n\|^2&\leq& C_\delta\|F_n\|_\mathcal{H}\|U_n\|_\mathcal{H}.
\end{eqnarray*}
From \eqref{Exponential003},   for $0\leq\xi\leq 1$,  result in 
\begin{equation}\label{Exponential003n}
\beta\kappa\delta\|A^\frac{1}{2}\theta_n\|^2\leq C_\delta\|F_n\|_\mathcal{H}\|U_n\|_\mathcal{H}.
\end{equation}
In addition to the estimative \eqref{dis-10},  for $0\leq\tau\leq 1$ and $0\leq\sigma\leq 1$,  result in  
\begin{eqnarray*}
\beta\gamma\mu_1\|A^\frac{\tau}{2}\Phi_n\|^2+\kappa\gamma\mu_2\|A^\frac{\sigma}{2}\Psi_n\|^2+\dfrac{\beta\kappa K}{\rho_3}\|A^\frac{\xi}{2}\Theta_n\|^2\leq C_\delta \|F_n\|_\mathcal{H}\|U_n\|_\mathcal{H}.
\end{eqnarray*}
Consequently,   $\|U_n\|_\mathcal{H}^2 \to 0.$
Therefore,  lead to  $\|U_n\|_\mathcal{H}\to  0$ but this is absurd,  since $\|U_n\|_\mathcal{H}=1$ for all $n\in{\mathbb N}$. Thus, $i{\mathbb R}\subset \rho(\mathcal{B}_1)$. This completes the proof.

\label{Lema001Analiticity}
Let $\delta> 0$. There exists a constant $C_\delta > 0$ such that the solutions of \eqref{Eq01B2}--\eqref{Eq03B2} and  \eqref{Eq08A}--\eqref{Eq09A}
for $|\lambda|\geq  \delta$  satisfy the inequality
\begin{eqnarray}\label{Eq004Lema02A}
(i)\quad |\lambda|\|\Phi\|^2\leq  C_\delta\|F\|_\mathcal{H}\|U\|_\mathcal{H}\qquad{\rm for}\qquad \frac{1}{2}\leq\tau\leq 1.\\
\label{Eq005Lema02A}
(ii)\quad |\lambda|\|\Psi\|^2\leq  C_\delta\|F\|_\mathcal{H}\|U\|_\mathcal{H}\qquad{\rm for}\qquad \frac{1}{2}\leq\sigma\leq 1.\\
\label{Eq006Lema02A}
(iii)\quad |\lambda|\|\Theta\|^2\leq C_\delta\|F\|_\mathcal{H}\|U\|_\mathcal{H}\qquad{\rm for}\qquad  \frac{1}{2}\leq\xi\leq 1.
\end{eqnarray}

{\bf Item $(i)$:}  of this lemma will be initially shown,  performing the duality product of \eqref{esp-20} for $\dfrac{\rho_1}{\mu_1}A^{-\tau}\lambda \Phi$,  and recalling that the operator $A^\nu$ is self-adjoint for all $\nu\in\mathbb{R}$,  results  in 
\begin{eqnarray*}
\lambda\|\Phi\|^2\hspace*{-0.3cm} &=& \dfrac{\kappa}{\mu_1}\langle{\lambda(-A\phi+\psi_x)},{A^{-\tau} \Phi}\rangle+\dfrac{\rho_1}{\mu_1}\langle{f^2},{\lambda A^{-\tau}\Phi}\rangle-i\dfrac{\rho_1}{\mu_1}\lambda^2\|A^{-\frac{\tau}{2}}\Phi\|^2\\
&=&\hspace*{-0.3cm}   i\dfrac{\kappa}{\mu_1}\|A^\frac{1-\tau}{2} \Phi\|^2+i\dfrac{\kappa}{\mu_1}\langle{A^\frac{1}{2}f^1},{A^{\frac{1}{2}-\tau}\Phi}\rangle+i\dfrac{\kappa}{\mu_1}\langle{\Psi},{A^{-\tau}\Phi_x}\rangle-i\dfrac{\kappa}{\mu_1}\langle{f_x^3},{A^{-\tau}\Phi}\rangle\\
& &-i\langle{f^2},{\Phi}\rangle -i\dfrac{\kappa}{\mu_1}\langle{f^2},{A^{1-\tau}\phi}\rangle +i\dfrac{\kappa}{\mu_1}\langle{A^{-\tau}f^2},{\psi_x}\rangle  +i\dfrac{\rho_1}{\mu_1}\|A^{-\frac{\tau}{2}}f^2\|^2-i\dfrac{\rho_1}{\mu_1}\lambda^2\|A^{-\frac{\theta}{2}}\Phi\|^2.
\end{eqnarray*}
Noting that: $\|A^{-\tau} \Phi_x\|^2=\langle{A^{-\tau}\Phi_x},{A^{-\tau}\Phi_x}\rangle=\langle{-A^{-\tau}\Phi_{xx}},{A^{-\tau}\Phi}\rangle=\|A^\frac{1-2\tau}{2} \Phi\|^2$,  taking real part  and considering that  $\frac{1}{2}\leq\tau\leq 1$  using estimative \eqref{dis-10} and using Cauchy-Schwarz and Young  inequalities,  for $\varepsilon>0$ exists $C_\varepsilon$,   such that
\begin{eqnarray*}
|\lambda|\|\Phi\|^2 & \leq & C_\delta\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\varepsilon\|A^{-\tau}\Phi_x\|^2+C_\varepsilon\|\Psi\|^2.
\end{eqnarray*}
As $0\leq\frac{\sigma}{2}$,  then from  estimative  \eqref{dis-10}  $\|\Psi\|^2\leq C_\delta\|F\|_\mathcal{H}\|U\|_\mathcal{H}$.  From the continuous embedding for  $|\lambda|\geq 1$,   the proof of item $(i)$ of this lemma is finished.



{\bf Item $(ii)$:}  Again similarly,  performing the duality product of \eqref{esp-40} for $\dfrac{\rho_2}{\mu_2}A^{-\sigma}\lambda \Psi$, using \eqref{esp-30}, and recalling the                                        self-adjointness of $A^\nu$,   $\nu \in\mathbb{R}$,  leads to 
\begin{eqnarray*}                     
\lambda\|\Psi\|^2 &=& i\dfrac{b}{\mu_2}\|A^\frac{1-\sigma}{2}\Psi\|^2+i\dfrac{b}{\mu_2}\langle{A^\frac{1}{2}f^3},{A^{\frac{1}{2}-\sigma}\Psi}\rangle+i\dfrac{\kappa}{\mu_2}\langle{A^{-\sigma}\Phi_x},{\Psi}\rangle+i\dfrac{\kappa}{\mu_2}\langle{f^1_x},{A^{-\sigma} \Psi}\rangle\\
& & +i\dfrac{\kappa}{\mu_2}\|A^{-\frac{\sigma}{2}}\Psi\|^2+i\dfrac{\kappa}{\mu_2}\langle{f^3},{A^{-\sigma}\Psi}\rangle-i\dfrac{b}{\rho_2}\langle{f^4},{A^{1-\sigma}\psi}\rangle-i\dfrac{\kappa}{\mu_2}\langle{f^4},{A^{-\sigma} \phi_x}\rangle\\
& & -i\dfrac{\kappa}{\mu_2}\langle{f^4},{A^{-\sigma}\psi}\rangle-i\dfrac{\beta}{\mu_2}\langle{f^4},{A^{-\sigma}\Theta}\rangle-i\langle{f^4},{\Psi}\rangle +   i\dfrac{\rho_2}{\mu_2}\|A^{-\frac{\sigma}{2}}f^4\|^2 -i\dfrac{\rho_2}{\mu_2}\lambda^2\|A^{-\frac{\sigma}{2}}\Psi\|^2.
\end{eqnarray*}
Noting that: $\|A^\frac{1-2\sigma}{2}\Phi\|^2=\|A^{-\sigma} \Phi_x\|^2$, taking real part,    considering $\frac{1}{2}\leq\sigma\leq 1$,    using Cauchy-Schwarz and Young  inequalities,  for $\varepsilon>0$ exists $C_\varepsilon$  such that
\begin{eqnarray*}
|\lambda|\|\Psi\|^2 & \leq & C_\delta\|F\|_\mathcal{H}\|U\|_\mathcal{H}+C_\varepsilon\|A^\frac{1-2\sigma}{2}\Phi\|^2+\varepsilon\|\Psi\|^2.
\end{eqnarray*}
As $-\frac{1-2\sigma}{2} \leq 0\Longleftrightarrow \frac{1}{2}\leq \sigma\leq 1$.   Considering  $|\lambda|\geq 1$,  using  estimative  \eqref{EstimaEquivExp1},    norms $\|F\|_\mathcal{H}$ and $\|U\|_\mathcal{H}$,    the proof of item $(ii)$ of this lemma is finished.


{\bf  Item $(iii)$:}  Finally,  let's prove the $(iii)$ item of this lemma, performing the duality product of \eqref{esp-60} for $\dfrac{\rho_3}{K}A^{-\xi}\lambda \Theta$, using \eqref{esp-30}, and recalling the   self-adjointness of $A^\nu$,   $\nu \in\mathbb{R}$,  result in 
\begin{eqnarray*}
\lambda\|\Theta\|^2 & = & -i\lambda^2\dfrac{\rho_3}{K}\|A^{-\frac{\xi}{2}}\Theta\|^2+i\dfrac{\delta}{K}\|A^\frac{1-\xi}{2}\Theta\|^2+i\dfrac{\delta}{K}\langle{A^\frac{1}{2}f^5},{A^{\frac{1}{2}-\xi}\Theta}\rangle-i\dfrac{\delta}{K}\langle{f^6},{A^{1-\xi}\theta}\rangle\\
& & +\dfrac{\gamma}{K}\langle{\sqrt{|\lambda|}\Psi},{\dfrac{\lambda}{\sqrt{|\lambda|}}A^{-\xi}\Theta_x}\rangle -i\dfrac{\gamma}{K}\langle{f^6},{A^{-\xi}\Psi_x}\rangle-i\langle{f^6},{\Theta}\rangle+i\dfrac{\rho_3}{K}\|A^{-\frac{\xi}{2}}f^6\|^2.
\end{eqnarray*}
Taking the real part,   applying Cauchy-Schwarz and Young inequalities,  for $\varepsilon>0$ exists $C_\varepsilon>0$ such that
\begin{multline}
|\lambda|\|\Theta\|^2\leq C\{ \|A^\frac{1-\xi}{2}\Theta\|^2+\|A^\frac{1}{2}f^5\|\|A^{\frac{1}{2}-\xi}\Theta\|\\
