i\lambda\theta-\Theta&=&f^5\quad{ \rm in}\quad D(A^\frac{1}{2}),\label{esp-50B}\\
i\lambda\Theta+\dfrac{\delta}{\rho_3}A\theta+\dfrac{\mu}{\rho_3}(\Phi_x+\Psi)+\dfrac{\gamma}{\rho_3}A^\xi\Theta&=& f^6\quad {\rm in}\quad D(A^0). \label{esp-60B}
