\|A^{-\frac{1}{2}}\Psi_2\|^2\leq C|\lambda|^{-\frac{4\sigma+2}{\sigma+1}}\{|\lambda|^\frac{2\sigma}{\sigma+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|_\mathcal{H}\}\quad\text{for}\quad 0\leq \sigma\leq 1.
\end{equation}
On the  other hand, from $\Psi_2=\Psi-\Psi_1$,  \eqref{dis-10B} and  as $0\leq\frac{\sigma}{2}\leq\frac{1}{2}$, the second inequality of \eqref{Eq112AnalyRRWB},  result in  
\begin{multline}\label{Eq114AnalyRRWB}
\|A^\frac{\sigma}{2} \Psi_2\|^2 \leq  C\{ \|A^\frac{\sigma}{2} \Psi\|^2+\|A^\frac{\sigma}{2}\Psi_1\|^2\}
\leq  C|\lambda|^{-\frac{2\sigma}{\sigma+1}}\{|\lambda|^\frac{2\sigma}{\sigma+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\}.
\end{multline}
Now using  interpolation inequality $0\in [-\frac{1}{2},\frac{\sigma}{2}]$.   Since

$0=\eta\bigg(-\dfrac{1}{2}\bigg)+(1-\eta)\dfrac{\sigma}{2},\quad {\rm for}\quad \eta=\dfrac{\sigma}{1+\sigma},$

 using \eqref{Eq113AnalyRRWB} and \eqref{Eq114AnalyRRWB} we get that
 \begin{eqnarray}
 \|\Psi_2\|^2 &\leq & C_\delta (\|A^{-\frac{1}{2}}\Psi_2\|^2)^{\eta} (\|A^\frac{\sigma}{2}\Psi_2\|^2)^{1-\eta} 
 \label{Eq118AnalyRRWB}
\leq C |\lambda|^{\frac{-4\sigma}{1+\sigma}}\{|\lambda|^\frac{2\sigma}{\sigma+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\}.
\end{eqnarray}

Also,   as $\|\Psi\|^2\leq  C\{\|\Psi_1\|^2+  \|\Psi_2\|^2\}$ from first inequality of  \eqref{Eq112AnalyRRWB}, estimative \eqref{Eq118AnalyRRWB} and as $|\lambda|^{-2}\leq |\lambda|^\frac{-2\sigma}{1+\sigma}$,   result in 
\begin{multline}\label{Eq119AnalyRRWB}
|\lambda|^\frac{2\sigma}{1+\sigma}\|\Psi\|\leq C_\delta\|F\|_\mathcal{H}\\
\Longleftrightarrow\; |\lambda|\|\Psi\|^2 \leq C_\delta|\lambda|^\frac{1-3\sigma}{\sigma+1}\{|\lambda|^\frac{2\sigma}{\sigma+1} \|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\}\quad\rm{for}\quad 0\leq\sigma\leq 1.
\end{multline}


{\bf Finally,  let's now estimate the missing term  $|\lambda|^\frac{2\xi}{1+\xi}\|\Theta\|$.}  Set $\Theta=\Theta_1+\Theta_2$,  where $\Theta_1\in D(A)$ and $\Theta_2\in D(A^0)$, with 
\begin{multline}\label{Eq110AnalyRRTB}
i\lambda \Theta_1+A \Theta_1=f^6 
\quad{\rm and}\quad
 i\lambda \Theta_2=-\dfrac{\delta}{\rho_3}A\theta -\dfrac{\mu}{\rho_3}\Phi_x-\dfrac{\mu}{\rho_3}\Psi-\dfrac{\gamma}{\rho_3}A^\xi \Theta+A\Theta_1.
\end{multline} 
Firstly,  applying the product duality  the first equation in \eqref{Eq110AnalyRRTB} by $\Theta_1$, then by $A\Theta_1$ and as the operators $A^\nu$ for all $\nu\in\mathbb{R}$ are self-adjoint,  result in
\begin{equation}\label{Eq112AnalyRRTB}
|\lambda|^2\|\Theta_1\|^2+|\lambda|\|A^\frac{1}{2}\Theta_1\|^2+\|A\Theta_1\|^2\leq C  \|F\|^2_\mathcal{H}.
\end{equation}


It arises  from the second equation in \eqref{Eq110AnalyRRTB}  that
\begin{equation*}
i\lambda A^{-\frac{1}{2}}\Theta_2= -\dfrac{\delta}{\rho_3}A^\frac{1}{2}\theta -\dfrac{\mu}{\rho_3}A^{-\frac{1}{2}}\Phi_x-\dfrac{\mu}{\rho_3}A^{-\frac{1}{2}}\Psi-\dfrac{\gamma}{\rho_3}A^{\xi-\frac{1}{2}} \Theta+A^\frac{1}{2}\Theta_1,
\end{equation*}
 then,  as  $\|A^{-\frac{1}{2}}\Phi_x\|^2=\|\Phi\|^2 $, $-\frac{1}{2}\leq 0$ and  $\xi-\frac{1}{2}\leq \frac{\xi}{2}$ taking into account the continuous embedding $D(A^{\theta_2}) \hookrightarrow D(A^{\theta_1}),\;\theta_2>\theta_1$ and using estimative \eqref{EstimaEquivExp2} and  estimative  \eqref{Eq112AnalyRRTB},    lead to
\begin{equation}\label{Eq113AnalyRRTB}
\|A^{-\frac{1}{2}}\Theta_2\|^2\leq C |\lambda|^{-\frac{4\xi+2}{\xi+1}}\{|\lambda|^\frac{2\xi}{\xi+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|_\mathcal{H}\}.
\end{equation}

On the  other hand, from $\Theta_2=\Theta-\Theta_1$,  \eqref{dis-10B} and  as $\frac{\xi}{2}\leq\frac{1}{2}$ the second inequality of \eqref{Eq112AnalyRRTB},  result in 
\begin{eqnarray}\label{Eq114AnalyRRTB}
\|A^\frac{\xi}{2} \Theta_2\|^2 & \leq &   C|\lambda|^{-\frac{2\xi}{\xi+1}}\{|\lambda|^\frac{2\xi}{\xi+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\}.
\end{eqnarray}
Now  using  interpolation inequality $0\in [-\frac{1}{2},\frac{\xi}{2}]$.   Since

$0=\eta\bigg(-\dfrac{1}{2}\bigg)+(1-\eta)\dfrac{\xi}{2},\quad {\rm for}\quad \eta=\dfrac{\xi}{1+\xi},$

 using \eqref{Eq113AnalyRRTB} and \eqref{Eq114AnalyRRTB} we get that
 \begin{eqnarray}
 \|\Theta_2\|^2 &\leq & C_\delta (\|A^{-\frac{1}{2}}\Theta_2\|^2)^{\eta} (\|A^\frac{\xi}{2}\Theta_2\|^2)^{1-\eta} 
 \label{Eq118AnalyRRTB}
\leq  |\lambda|^{\frac{-2\xi}{\xi+1}}\{\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\}
\end{eqnarray}

Also as, $\|\Theta\|^2\leq C\{ \|\Theta_1\|^2+ \|\Theta_2\|^2\}$ from first inequality of  \eqref{Eq112AnalyRRTB},  \eqref{Eq118AnalyRRTB} and as $|\lambda|^{-2}\leq |\lambda|^\frac{-4\xi}{1+\xi}$,  result in 
\begin{multline}\label{Eq119AnalyRRTB}
|\lambda|^\frac{2\xi}{1+\xi}\|\Theta\|\leq C_\delta\|F\|_\mathcal{H}\\
\Longleftrightarrow\quad |\lambda|\|\Theta\|^2\leq C_\delta |\lambda|^\frac{1-3\xi}{1+\xi}\{|\lambda|^\frac{2\xi}{\xi+1} \|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F||^2_\mathcal{H}\}\quad\rm{for}\quad 0\leq\xi\leq 1.
\end{multline}




Finally,   using    \eqref{Eq119AnalyRRB},    \eqref{Eq119AnalyRRWB} and \eqref{Eq119AnalyRRTB} in the inequality item $(i)$ of Lemma \ref{RegularidadB},   result in 
\begin{multline*}                     
\beta\gamma[\kappa\|\phi_x+\psi\|^2+b\|A^\frac{1}{2}\psi\|^2]
 \leq
C\big\{ |\lambda|^\frac{-2\tau}{1+\tau}+|\lambda|^\frac{-2\sigma}{1+\sigma}+|\lambda|^\frac{-2\xi}{1+\xi}+|\lambda|^{-1}\big\} \|F\|_\mathcal{H}\|U\|_\mathcal{H}\\
+C\{ |\lambda|^{-\frac{4\tau}{\tau+1}}+ |\lambda|^{-\frac{4\sigma}{\sigma+1}}+ |\lambda|^{-\frac{4\xi}{\xi+1}}\}\|F\|^2_\mathcal{H},
\end{multline*}
then
\begin{multline}\label{Eq020GevreyB}
\beta\gamma|\lambda|[\kappa\|\phi_x+\psi\|^2+b\|A^\frac{1}{2}\psi\|^2]\\
 \leq
C_\delta\left\{ \begin{array}{ccc}
 |\lambda|^\frac{1-3\tau}{1+\tau}\{ |\lambda|^\frac{2\tau}{\tau+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\} &\text{for} & \tau\leq \sigma\quad{\rm and}\quad \tau\leq \xi, 
 \\\\
  |\lambda|^\frac{1-3\sigma}{1+\sigma}\{ |\lambda|^\frac{2\sigma}{\sigma+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\} &\text{for} & \sigma \leq \tau\quad{\rm and}\quad \sigma\leq \xi,\\\\
   |\lambda|^\frac{1-3\xi}{1+\xi}\{ |\lambda|^\frac{2\xi}{\xi+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\} &\text{for} & \xi\leq \sigma\quad{\rm and}\quad \xi\leq \tau.
\end{array}\right.
\end{multline}
Analogously, using  \eqref{Eq119AnalyRRB} and \eqref{Eq119AnalyRRTB} in the inequality item $(ii)$ of Lemma \ref{RegularidadB},   result in 
\begin{equation}\label{Eq021GevreyB}
\delta|\lambda| \|A^\frac{1}{2}\theta\|^2
 \leq
C_\delta \left\{ \begin{array}{ccc}
 |\lambda|^\frac{1-3\tau}{1+\tau}\{ |\lambda|^\frac{2\tau}{\tau+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\} &\text{for} & \tau\leq \xi, 
\\\\
   |\lambda|^\frac{1-3\xi}{1+\xi}\{ |\lambda|^\frac{2\xi}{\xi+1}\|F\|_\mathcal{H}\|U\|_\mathcal{H}+\|F\|^2_\mathcal{H}\} &\text{for} &  \xi\leq \tau.
\end{array}\right.
\end{equation}
Finally,  summing the    the estimates  \eqref{Eq119AnalyRRB},  \eqref{Eq119AnalyRRWB}, \eqref{Eq119AnalyRRTB}, \eqref{Eq020GevreyB} and  \eqref{Eq021GevreyB} and applying Young inequality, we obtain
\begin{equation*}
\left\{  \begin{array}{ccc}
 |\lambda|^\frac{2\tau}{\tau+1}\|U\|_\mathcal{H}\leq C_\delta|\|F\|_\mathcal{H} &\text{for} & \tau\leq \sigma\quad{\rm and}\quad \tau\leq \xi, 
 \\\\
  |\lambda|^\frac{2\sigma}{1+\sigma}\|U\|_\mathcal{H}\leq C_\delta\|F\|_\mathcal{H} &\text{for} & \sigma \leq \tau\quad{\rm and}\quad \sigma\leq \xi,\\\\
   |\lambda|^\frac{2\xi}{1+\xi}\|U\|_\mathcal{H}\leq C_\delta \|F\|_\mathcal{H} & \text{for} & \xi\leq \sigma\quad{\rm and}\quad \xi\leq \tau.
\end{array}\right.
\end{equation*}
 for $(\tau,\sigma, \xi)\in (0,1)^3$  the proof of this Theorem \ref{GevreyLaminadoB},  is finished.

\label{Lema001AnaliticityB}
Let $\delta> 0$. There exists a constant $C_\delta > 0$ such that the solutions of \eqref{Eq01B2}--\eqref{Eq09A}
for $|\lambda|\geq  \delta$  satisfy the inequality
\begin{eqnarray}\label{Eq004Lema02B}
(i)\quad |\lambda|[\|\Phi\|^2 +\|\Theta\|^2]\leq  C_\delta\|F\|_\mathcal{H}\|U\|_\mathcal{H}\qquad{\rm for}\qquad \frac{1}{2}\leq\tau=\xi\leq 1.
\\
\label{Eq005Lema02B}
(ii)\quad |\lambda|\|\Psi\|^2\leq  C_\delta\|F\|_\mathcal{H}\|U\|_\mathcal{H}\qquad{\rm for}\qquad \frac{1}{2}\leq\sigma\leq 1.
\end{eqnarray}

{\bf Item $(i)$:} 
Realizing the duality product of \eqref{esp-20B}  with $\dfrac{\rho_1}{\gamma}A^{-\tau}\lambda \Phi$  and using the property that the operator $A^\nu$ is self-adjoint for all $\nu\in \mathbb{R}$ and using the equation \eqref{esp-10B},  result in 
\begin{eqnarray}
\dfrac{\mu_1}{\gamma}\lambda\|\Phi\|^2 &=& i\dfrac{\kappa}{\gamma}\|A^\frac{1-\tau}{2} \Phi\|^2+i\dfrac{\kappa}{\gamma}\langle{A^\frac{1}{2}f^1},{A^{\frac{1}{2}-\tau}\Phi}\rangle+i\dfrac{\kappa}{\gamma}\langle{\Psi},{A^{-\tau}\Phi_x}\rangle-i\dfrac{\kappa}{\mu_1}\langle{f_x^3},{A^{-\tau}\Phi}\rangle\\
\label{Eq006Lema02B2}
& &-i\langle{f^2},{\Phi}\rangle -i\dfrac{\kappa}{\gamma}\langle{f^2},{A^{1-\tau}\phi}\rangle +i\dfrac{\kappa}{\gamma}\langle{A^{-\tau}f^2},{\psi_x}\rangle+i\dfrac{\rho_1}{\gamma}\|A^{-\frac{\tau}{2}}f^2\|^2  \\
\nonumber
& & -i\dfrac{\rho_1}{\gamma}\lambda^2\|A^{-\frac{\theta}{2}}\Phi\|^2 +\dfrac{\mu}{\gamma}\langle{\Theta},{\lambda A^{-\tau}\Phi_x}\rangle.
\end{eqnarray}


On the other hand,  now performing the duality product of \eqref{esp-60B} for $\dfrac{\rho_3}{\gamma}A^{-\xi}\lambda \Theta$, using \eqref{esp-30B}, and as
the operators $A^\nu$ for all $\nu\in\mathbb{R}$ are self-adjoint,  result in 
\begin{eqnarray}
\nonumber
\lambda\|\Theta\|^2 \hspace*{-0.3cm}& = &\hspace*{-0.3cm} -i\lambda^2\dfrac{\rho_3}{\gamma}\|A^{-\frac{\xi}{2}}\Theta\|^2+i\dfrac{\delta}{\gamma}\|A^\frac{1-\xi}{2}\Theta\|^2+i\dfrac{\delta}{\gamma}\langle{A^\frac{1}{2}f^5},{A^{\frac{1}{2}-\xi}\Theta}\rangle-i\dfrac{\delta}{\gamma}\langle{f^6},{A^{1-\xi}\theta}\rangle-i\dfrac{\mu}{\gamma}\langle{f^6},{A^{-\xi}\Phi_x}\rangle\\
\label{Eq006Lema02B3}
& & -i\dfrac{\mu}{\gamma}\langle{f^6},{A^{-\xi}\Psi}\rangle -i\langle{f^6},{\Theta}\rangle+i\dfrac{\rho_3}{\gamma}\|A^{-\frac{\xi}{2}}f^6\|^2-\dfrac{\mu}{\gamma}\langle{\lambda A^{-\xi}\Phi_x},{\Theta}\rangle.
\end{eqnarray}
Imposing the condition $\tau=\xi$ and since ${\rm Re}\{\langle{\Theta},{\lambda A^{-\tau}\Phi_x}\rangle-\langle{\lambda A^{-\tau}\Phi_x},{\Theta}\rangle\}=0$,  adding the equations \eqref{Eq006Lema02B2} and \eqref{Eq006Lema02B3} and then taking the real part, result in 
\begin{eqnarray*}
\lambda\bigg [ \dfrac{\mu_1}{\gamma}\|\Phi\|^2+\|\Theta\|^2\bigg] &= & i\dfrac{\kappa}{\gamma}\langle{A^\frac{1}{2}f^1},{A^{\frac{1}{2}-\tau}\Phi}\rangle+i\dfrac{\kappa}{\gamma}\langle{\Psi},{A^{-\tau}\Phi_x}\rangle-i\dfrac{\kappa}{\mu_1}\langle{f_x^3},{A^{-\tau}\Phi}\rangle-i\langle{f^2},{\Phi}\rangle\\
& & -i\dfrac{\kappa}{\gamma}\langle{f^2},{A^{1-\tau}\phi}\rangle +i\dfrac{\kappa}{\gamma}\langle{A^{-\tau}f^2},{\psi_x}\rangle  +i\dfrac{\delta}{\gamma}\langle{A^\frac{1}{2}f^5},{A^{\frac{1}{2}-\xi}\Theta}\rangle
\\
& & -i\dfrac{\delta}{\gamma}\langle{f^6},{A^{1-\xi}\theta}\rangle-i\dfrac{\mu}{\gamma}\langle{f^6},{A^{-\xi}\Phi_x}\rangle -i\dfrac{\mu}{\gamma}\langle{f^6},{A^{-\xi}\Psi}\rangle -i\langle{f^6},{\Theta}\rangle
\end{eqnarray*}
From $|i\frac{\kappa}{\gamma}\langle{\Psi},{A^{-\tau}\Psi_x}\rangle|\leq C\{\|\Psi\|^2+\|A^\frac{1-2\tau}{2}\Phi\|^2\}$ and  $\frac{1}{2}\leq\tau=\xi\leq 1$,   applying Cauchy-Schwarz and Young inequalities,  norms $\|F\|_\mathcal{H}$ and $\|U\|_\mathcal{H}$,  the proof of item $(i)$ of this lemma is finished.\\



{\bf Item $(ii)$:}  Similarly,   performing the duality product of \eqref{esp-40B} for $\dfrac{\rho_2}{\mu_2}A^{-\sigma}\lambda \Psi$, using \eqref{esp-30B}, and recalling the                                        self-adjointness of $A^\nu$,   $\nu \in\mathbb{R}$,  lead to 
\begin{eqnarray*}                     
\lambda\|\Psi\|^2 
\hspace*{-0.2cm}&=&\hspace*{-0.2cm}  -i\dfrac{\rho_2}{\mu_2}\lambda^2\|A^{-\frac{\sigma}{2}}\Psi\|^2+i\dfrac{b}{\mu_2}\|A^\frac{1-\sigma}{2}\Psi\|^2+i\dfrac{b}{\mu_2}\langle{A^\frac{1}{2}f^3},{A^{\frac{1}{2}-\sigma}\Psi}\rangle-i\dfrac{\kappa}{\mu_2}\langle{\Phi},{A^{-\sigma}\Psi_x}\rangle\\
& & +i\dfrac{\kappa}{\mu_2}\langle{f^1_x},{A^{-\sigma}\Psi}\rangle+i\dfrac{\kappa}{\mu_2}\|A^{-\frac{\sigma}{2}}\Psi\|^2+i\dfrac{\kappa}{\mu_2}\langle{f^3},{A^{-\sigma}\Psi}\rangle \\
& &+\dfrac{\mu}{\mu_2}\langle{\sqrt{|\lambda|}\Theta},{\dfrac{\lambda}{\sqrt{|\lambda|}}A^{-\sigma}\Psi}\rangle-i\dfrac{b}{\mu_2}\langle{f^4},{A^{1-\sigma}\Psi}\rangle-i\dfrac{\kappa}{\mu_2}\langle{f^4},{A^{-\sigma}\phi_x}\rangle\\
& &-i\dfrac{\kappa}{\mu_2}\langle{f^4},{A^{-\sigma}\psi}\rangle +i\dfrac{\mu}{\mu_2}\langle{f^4},{A^{-\sigma}\Theta}\rangle-i\langle{f^4},{\Psi}\rangle+i\dfrac{\rho_2}{\mu_2}\|f^4\|^2.
\end{eqnarray*}
Noting that:  For $\frac{1}{2}\leq\sigma\leq 1$ lead to   $\frac{1-\sigma}{2}\leq \frac{\sigma}{2}$,  $\frac{1}{2}-\sigma\leq 0$  and $\frac{1-2\sigma}{2}\leq 0$,  on the other hand  as $\|A^{-\sigma} \Psi_x\|^2=\|A^\frac{1-2\sigma}{2}\Psi\|^2$,  taking real part  and considering that  $\frac{1}{2}\leq\sigma\leq 1$  and using Cauchy-Schwarz and Young  inequalities,  norms $\|F\|_\mathcal{H}$ and $\|U\|_\mathcal{H}$,   for $\varepsilon>0$,  exists $C_\varepsilon>0$  independent of $\lambda$ such that
\begin{eqnarray*}
|\lambda|\|\Psi\|^2 & \leq & C_\delta\|F\|_\mathcal{H}\|U\|_\mathcal{H}+C\{\|\Phi\|^2+\|\Psi\|^2\}+C_\varepsilon|\lambda|\|\Theta\|^2+\varepsilon|\lambda|\|\Psi\|^2.
\end{eqnarray*}
From   \eqref{EstimaEquivExp2} and item $(i)$ of this lemma,    the proof of item $(ii)$ of this lemma is finished.

